T({name:'Password Generator',id:'password-generator',pop:14,kw:'strong secure random',desc:'Create strong, random passwords instantly',run(r){const len=h('input',{class:'uin',type:'range',min:6,max:64,value:16});const lv=h('b',{},'16');const up=U.chk('A-Z',true),lo=U.chk('a-z',true),nu=U.chk('0-9',true),sy=U.chk('!@#$',true),am=U.chk('No look-alikes (0/O, l/1)',false);const res=U.res(h('div'));
  const g=genTool(r,{opts:()=>[U.field(h('span',{},'Length: ',lv),len),up,lo,nu,sy,am],rows:3,gen:()=>{lv.textContent=len.value;let s='';if(up.input.checked)s+='ABCDEFGHIJKLMNOPQRSTUVWXYZ';if(lo.input.checked)s+='abcdefghijklmnopqrstuvwxyz';if(nu.input.checked)s+='0123456789';if(sy.input.checked)s+='!@#$%^&*()-_=+[]{};:,.?';if(am.input.checked)s=s.replace(/[0O1lI]/g,'');if(!s)return'Pick at least one character type';const a=new Uint32Array(+len.value);crypto.getRandomValues(a);const p=[...a].map(v=>s[v%s.length]).join('');const bits=Math.round(len.value*Math.log2(s.length));res.set([['Strength',bits>=100?'💪 Very strong':bits>=70?'Strong':bits>=50?'OK':'Weak'],['Entropy',bits+' bits']]);return p}});
  r.append(res.el);r.querySelector('.urow').addEventListener('input',g.run)}});

T({name:'UUID Generator',id:'uuid-generator',kw:'guid unique id',desc:'Generate random v4 UUIDs in bulk',run(r){const n=U.num(5);const up=U.chk('UPPERCASE');genTool(r,{opts:()=>[U.field('How many',n),up],gen:()=>Array.from({length:Math.min(1000,+n.value||1)},()=>{const u=crypto.randomUUID();return up.input.checked?u.toUpperCase():u}).join('\n')})}});

T({name:'JSON Validator',id:'json-validator',kw:'format prettify lint beautify',desc:'Validate, format and minify JSON',run(r){const ind=U.sel([['2','2 spaces'],['4','4 spaces'],['0','Minify']]);const st=h('div',{class:'res'});textTool(r,{ph:'{"paste":"json here"}',opts:()=>[U.field('Output',ind)],fn:t=>{try{const o=JSON.parse(t);st.innerHTML='<div class="rcard"><small>Status</small><b style="color:#4ade80">✓ Valid JSON</b></div>';return+ind.value?JSON.stringify(o,null,+ind.value):JSON.stringify(o)}catch(e){const m=e.message.match(/position (\d+)/);let where='';if(m){const pos=+m[1];const before=t.slice(0,pos);where=` (line ${before.split('\n').length}, column ${pos-before.lastIndexOf('\n')})`}st.innerHTML='';st.append(h('div',{class:'rcard'},h('small',{},'Status'),h('b',{style:'color:#ff6b8a;font-size:15px'},'✗ '+e.message+where)));return''}}});r.append(st)}});

T({name:'Regex Tester',id:'regex-tester',kw:'regular expression pattern match',desc:'Test regular expressions with live highlighting',run(r){const pat=U.inp({value:'\\b\\w+@\\w+\\.\\w+\\b',class:'uin mono'}),fl=U.inp({value:'g',style:'max-width:90px'});const txt=U.ta({value:'Contact: hello@dorapdf.com or support@site.io'});const hi=h('div',{class:'rcard mono',style:'white-space:pre-wrap;line-height:1.7;margin-top:12px'});const tb=h('div');
  const run=()=>{let re;try{re=new RegExp(pat.value,fl.value.includes('g')?fl.value:fl.value+'g')}catch(e){hi.textContent='⚠️ '+e.message;tb.innerHTML='';return}const s=txt.value;let out='',last=0,ms=[];for(const m of s.matchAll(re)){if(m[0]==='')break;out+=esc(s.slice(last,m.index))+`<mark style="background:#ff2e88;color:#fff;border-radius:4px;padding:0 2px">${esc(m[0])}</mark>`;last=m.index+m[0].length;ms.push(m)}out+=esc(s.slice(last));hi.innerHTML=out||'&nbsp;';
    tb.innerHTML='';const t=h('table',{class:'utable'},h('tr',{},h('th',{},'#'),h('th',{},'Match'),h('th',{},'Index'),h('th',{},'Groups')));ms.slice(0,200).forEach((m,i)=>t.append(h('tr',{},h('td',{},i+1),h('td',{class:'mono'},m[0]),h('td',{},m.index),h('td',{class:'mono'},m.slice(1).join(' | ')))));tb.append(h('p',{class:'note'},ms.length+' match'+(ms.length===1?'':'es')),t)};
  r.append(U.row(U.field('Pattern',pat),U.field('Flags',fl)),h('div',{class:'urow'},U.field('Test text',txt,'full')),hi,tb);[pat,fl,txt].forEach(e=>e.addEventListener('input',run));run()}});

T({name:'Base64 Encoder / Decoder',id:'base64',kw:'encode decode',desc:'Encode or decode Base64 text and files',run(r){const m=U.sel([['e','Encode → Base64'],['d','Decode ← Base64']]);textTool(r,{opts:()=>[U.field('Mode',m)],fn:t=>m.value==='e'?btoa(unescape(encodeURIComponent(t))):decodeURIComponent(escape(atob(t.trim())))});
  const fo=h('div');r.append(h('p',{class:'note',style:'margin-top:20px'},'Or encode a file:'));U.drop(r,{onFiles:async fs=>{const b=new Uint8Array(await readAB(fs[0]));let s='';for(let i=0;i<b.length;i+=8192)s+=String.fromCharCode(...b.subarray(i,i+8192));const d=`data:${fs[0].type||'application/octet-stream'};base64,`+btoa(s);fo.innerHTML='';const ta=U.ta({readonly:true,value:d});fo.append(U.field('Data URL',ta,'full'),U.copy(()=>ta.value))}});r.append(fo)}});

