function parseCSV(t,sep){const rows=[];let row=[],f='',q=false;for(let i=0;i<t.length;i++){const c=t[i];if(q){if(c==='"'){if(t[i+1]==='"'){f+='"';i++}else q=false}else f+=c}else if(c==='"')q=true;else if(c===sep){row.push(f);f=''}else if(c==='\n'||c==='\r'){if(c==='\r'&&t[i+1]==='\n')i++;row.push(f);rows.push(row);row=[];f=''}else f+=c}if(f||row.length){row.push(f);rows.push(row)}return rows.filter(r=>r.some(x=>x!==''))}
T({name:'CSV to JSON Converter',id:'csv-to-json',kw:'json to csv excel data',desc:'Convert CSV to JSON and JSON back to CSV',run(r){const m=U.sel([['cj','CSV → JSON'],['jc','JSON → CSV']]);const sep=U.sel([[',','Comma'],[';','Semicolon'],['\t','Tab']]);
  textTool(r,{ph:'name,age\nAli,24\nSara,22',opts:()=>[U.field('Mode',m),U.field('Separator',sep)],dl:'data.txt',fn:t=>{if(m.value==='cj'){const rows=parseCSV(t,sep.value);const hd=rows.shift();return JSON.stringify(rows.map(rw=>Object.fromEntries(hd.map((k,i)=>{const v=rw[i]??'';return[k,v!==''&&!isNaN(v)?+v:v]}))),null,2)}const a=JSON.parse(t);const arr=Array.isArray(a)?a:[a];const keys=[...new Set(arr.flatMap(o=>Object.keys(o)))];const q=v=>{v=v==null?'':typeof v==='object'?JSON.stringify(v):String(v);return /[",\n;\t]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v};return[keys.join(sep.value),...arr.map(o=>keys.map(k=>q(o[k])).join(sep.value))].join('\n')}})}});

T({name:'ZIP Extractor',id:'zip-extractor',file:true,kw:'unzip open archive',desc:'Open ZIP files and download what is inside',run(r){fileTool(r,{accept:'.zip,application/zip',auto:true,go:async(fs,{out,prog})=>{await loadScript(CDN.jszip);const z=await JSZip.loadAsync(await readAB(fs[0]));const files=Object.values(z.files).filter(f=>!f.dir);if(!files.length)throw new Error('The ZIP is empty');for(let i=0;i<Math.min(files.length,300);i++){const f=files[i];out.add(f.name.split('/').pop(),await f.async('blob'),f.name);prog((i+1)/files.length)}}})}});

T({name:'Video Compressor',id:'video-compressor',file:true,kw:'reduce video size mp4',desc:'Shrink video file size right in your browser',note:'🔒 Processed on your device. Compression runs in real time (a 1-minute video takes about 1 minute). Output is WebM.',run(r){const br=U.sel([['400000','Small (400 kbps)'],['1000000','Balanced (1 Mbps)'],['2500000','High (2.5 Mbps)']],{value:'1000000'});const res=U.sel([['1','Original resolution'],['0.75','75%'],['0.5','50%']]);
  fileTool(r,{accept:'video/*',opts:()=>U.row(U.field('Quality',br),U.field('Resolution',res)),btn:'Compress video ✦',go:async(fs,{out,prog})=>{const f=fs[0];const v=h('video',{playsinline:true});v.src=URL.createObjectURL(f);await new Promise((ok,no)=>{v.onloadedmetadata=ok;v.onerror=()=>no(new Error('This video format is not supported by your browser'))});
    const W=Math.round(v.videoWidth*res.value/2)*2,H=Math.round(v.videoHeight*res.value/2)*2;const c=canvasOf(W,H),x=c.getContext('2d');const stream=c.captureStream(30);
    try{const ac2=new AudioContext();const src=ac2.createMediaElementSource(v);const dst=ac2.createMediaStreamDestination();src.connect(dst);dst.stream.getAudioTracks().forEach(t=>stream.addTrack(t))}catch(e){}
    const mime=['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm'].find(m=>MediaRecorder.isTypeSupported(m));const rec=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:+br.value,audioBitsPerSecond:96000});const chunks=[];rec.ondataavailable=e=>e.data.size&&chunks.push(e.data);
    const done=new Promise(ok=>rec.onstop=ok);rec.start(1000);await v.play();let raf;const draw=()=>{x.drawImage(v,0,0,W,H);prog(v.currentTime/v.duration*.98);raf=requestAnimationFrame(draw)};draw();await new Promise(ok=>v.onended=ok);cancelAnimationFrame(raf);rec.stop();await done;
    const b=new Blob(chunks,{type:'video/webm'});out.add(base(f.name)+'-compressed.webm',b,`${base(f.name)}-compressed.webm · ${Math.max(0,Math.round(100-b.size/f.size*100))}% smaller`)}})}});

T({name:'ASCII Art Generator',id:'ascii-art',kw:'text art image',desc:'Turn photos or text into ASCII art',run(r){const w=U.sel([['60','60 chars'],['100','100 chars'],['140','140 chars']],{value:'100'});const inv=U.chk('Invert (for dark backgrounds)',false);const ta=U.ta({readonly:true,style:'font-size:8px;line-height:1;min-height:300px;white-space:pre'});let img=null;
  const run=()=>{if(!img)return;const W=+w.value,H=Math.round(W*img.naturalHeight/img.naturalWidth*.5);const c=canvasOf(W,H),x=c.getContext('2d');x.drawImage(img,0,0,W,H);const d=x.getImageData(0,0,W,H).data;let ch='@%#*+=-:. ';if(inv.input.checked)ch=ch.split('').reverse().join('');let s='';for(let y=0;y<H;y++){for(let i=0;i<W;i++){const k=(y*W+i)*4;const l=(d[k]*.3+d[k+1]*.59+d[k+2]*.11)/255;s+=ch[Math.min(ch.length-1,Math.floor(l*ch.length))]}s+='\n'}ta.value=s};
  U.drop(r,{accept:'image/*',onFiles:async fs=>{img=await imgFromFile(fs[0]);run()}});r.append(U.row(U.field('Width',w),inv),h('div',{class:'urow'},U.field('ASCII art',ta,'full')),U.copy(()=>ta.value));[w,inv.input].forEach(e=>e.addEventListener('change',run))}});

T({name:'Binary to Text Translator',id:'binary-to-text',kw:'binary code 0101',desc:'Translate binary to text and text to binary',run(r){const m=U.sel([['tb','Text → Binary'],['bt','Binary → Text']]);textTool(r,{opts:()=>[U.field('Mode',m)],fn:t=>m.value==='tb'?[...new TextEncoder().encode(t)].map(b=>b.toString(2).padStart(8,'0')).join(' '):new TextDecoder().decode(new Uint8Array(t.replace(/[^01]/g,'').match(/.{1,8}/g).map(b=>parseInt(b,2))))})}});

const BR={a:'⠁',b:'⠃',c:'⠉',d:'⠙',e:'⠑',f:'⠋',g:'⠛',h:'⠓',i:'⠊',j:'⠚',k:'⠅',l:'⠇',m:'⠍',n:'⠝',o:'⠕',p:'⠏',q:'⠟',r:'⠗',s:'⠎',t:'⠞',u:'⠥',v:'⠧',w:'⠺',x:'⠭',y:'⠽',z:'⠵',' ':' ',',':'⠂',';':'⠆',':':'⠒','.':'⠲','!':'⠖','?':'⠦','-':'⠤',"'":'⠄'};const BRN={1:'a',2:'b',3:'c',4:'d',5:'e',6:'f',7:'g',8:'h',9:'i',0:'j'};const BRR=Object.fromEntries(Object.entries(BR).map(([k,v])=>[v,k]));
T({name:'Braille Translator',id:'braille-translator',desc:'Convert text to Braille and back',run(r){const m=U.sel([['tb','Text → Braille'],['bt','Braille → Text']]);textTool(r,{opts:()=>[U.field('Mode',m)],fn:t=>{if(m.value==='tb'){let o='',num=false;for(const c of t.toLowerCase()){if(/\d/.test(c)){if(!num){o+='⠼';num=true}o+=BR[BRN[c]]}else{num=false;o+=BR[c]??c}}return o}let o='',num=false;for(const c of t){if(c==='⠼'){num=true;continue}const l=BRR[c];if(num&&l&&'abcdefghij'.includes(l)){o+='1234567890'['abcdefghij'.indexOf(l)];continue}num=false;o+=l??c}return o}})}});

T({name:'Color Code Converter',id:'color-code-converter',kw:'hex rgb hsl cmyk',desc:'Convert colors between HEX, RGB, HSL and CMYK',run(r){const inp=U.inp({value:'#ff2e88'});const pk=U.inp({type:'color',value:'#ff2e88'});const res=U.res(h('div'));const sw=h('div',{style:'height:80px;border-radius:16px;margin-top:14px;border:1px solid var(--line)'});
  const run=v=>{const x=canvasOf(1,1).getContext('2d');x.fillStyle='#000';x.fillStyle=v;const n=x.fillStyle;x.fillRect(0,0,1,1);const [R,G,B]=x.getImageData(0,0,1,1).data;const hex='#'+[R,G,B].map(q=>q.toString(16).padStart(2,'0')).join('');const [hh,s,l]=rgb2hsl(R,G,B);const k=1-Math.max(R,G,B)/255;const cm=q=>k===1?0:Math.round((1-q/255-k)/(1-k)*100);
    res.set([['HEX',hex.toUpperCase()],['RGB',`rgb(${R}, ${G}, ${B})`],['HSL',`hsl(${hh}, ${s}%, ${l}%)`],['CMYK',`${cm(R)}, ${cm(G)}, ${cm(B)}, ${Math.round(k*100)}`]]);sw.style.background=hex;pk.value=hex};
  inp.oninput=()=>run(inp.value);pk.oninput=()=>{inp.value=pk.value;run(pk.value)};r.append(U.row(U.field('Any color (hex, rgb(), hsl(), or name like "teal")',inp),U.field('Pick',pk)),sw,res.el);res.el.addEventListener('click',e=>{const b=e.target.closest('.rcard');if(b)copyText(b.querySelector('b').textContent)});run(inp.value)}});

T({name:'Date to Age Converter',id:'date-to-age',kw:'age calculator birthday',desc:'Calculate exact age from a date of birth',run(r){const t=new Date().toISOString().slice(0,10);calcTool(r,{fields:[{k:'d',l:'Date of birth',t:'date',v:'2000-01-01'},{k:'n',l:'Age on date',t:'date',v:t}],calc:v=>{const a=new Date(v.d),b=new Date(v.n);if(isNaN(a)||isNaN(b))return[['Enter dates','—']];let y=b.getFullYear()-a.getFullYear(),m=b.getMonth()-a.getMonth(),d=b.getDate()-a.getDate();if(d<0){m--;d+=new Date(b.getFullYear(),b.getMonth(),0).getDate()}if(m<0){y--;m+=12}const days=Math.floor((b-a)/864e5);const nb=new Date(b.getFullYear(),a.getMonth(),a.getDate());if(nb<b)nb.setFullYear(nb.getFullYear()+1);
  return[['Age',`${y} years, ${m} months, ${d} days`,true],['Total months',fmtN(y*12+m,0)],['Total weeks',fmtN(Math.floor(days/7),0)],['Total days',fmtN(days,0)],['Next birthday in',Math.ceil((nb-b)/864e5)+' days'],['Born on a',a.toLocaleDateString('en-US',{weekday:'long'})]]}})}});

