T({name:'JWT Decoder',id:'jwt-decoder',kw:'json web token',desc:'Decode JWT header and payload instantly',run(r){const res=h('div');textTool(r,{ph:'eyJhbGciOi…',fn:t=>{const p=t.trim().split('.');if(p.length<2)throw new Error('Not a valid JWT');const dec=s=>JSON.parse(decodeURIComponent(escape(atob(s.replace(/-/g,'+').replace(/_/g,'/').padEnd(Math.ceil(s.length/4)*4,'=')))));const hd=dec(p[0]),pl=dec(p[1]);res.innerHTML='';if(pl.exp){const ex=new Date(pl.exp*1000);res.append(h('div',{class:'rcard',style:'margin-top:12px'},h('small',{},'Expires'),h('b',{style:'font-size:16px'},ex.toLocaleString()+(ex<new Date()?' (expired)':' (valid)'))))}return'// HEADER\n'+JSON.stringify(hd,null,2)+'\n\n// PAYLOAD\n'+JSON.stringify(pl,null,2)}});r.append(res,h('p',{class:'note'},'🔒 Decoded locally. The signature is not verified.'))}});

const LEET={a:'4',b:'8',e:'3',g:'9',i:'1',l:'1',o:'0',s:'5',t:'7',z:'2'},LEET2={a:'/-\\',b:'|3',c:'(',d:'|)',e:'3',f:'|=',g:'6',h:'|-|',i:'!',j:'_|',k:'|<',l:'|_',m:'|\\/|',n:'|\\|',o:'()',p:'|*',q:'0_',r:'|2',s:'$',t:'+',u:'|_|',v:'\\/',w:'\\/\\/',x:'><',y:'`/',z:'2'};
